// Small compositions of the games' own visual language, rather than cropped screens.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=(x,y,s,size=24,color='#243d39',extra='')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${color}" ${extra}>${esc(s)}</text>`;
const rect=(x,y,w,h,fill='#fff',stroke='none',r=15)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${fill}" stroke="${stroke}" stroke-width="3"/>`;
const tile=(x,y,label,color='#fff7e4',angle=0)=>`<g transform="translate(${x} ${y}) rotate(${angle})">${rect(0,5,76,82,'#24304a')}${rect(0,0,76,82,color,'#24304a')}${text(38,55,label,43,'#24304a','text-anchor="middle" font-weight="800"')}</g>`;
const audio=(x,y,color='#628e91')=>`<g transform="translate(${x} ${y})" fill="none" stroke="${color}" stroke-width="5" stroke-linecap="round"><path d="M0 0v24l16-8V8Z" fill="${color}" stroke="none"/><path d="M24 3q14 9 0 18m10-27q23 18 0 36"/></g>`;
const wave=(x,y,color='#708ec5')=>`<g transform="translate(${x} ${y})" stroke="${color}" stroke-width="5" stroke-linecap="round">${[12,28,44,20,54,34,16,40,26].map((h,i)=>`<path d="M${i*12} ${-h/2}v${h}"/>`).join('')}</g>`;
function picture(cards,word,x,y,size=90){const c=cards.find(c=>c.en===word);return c?.image?.url?`<image href="${esc(c.image.url)}" x="${x}" y="${y}" width="${size}" height="${size}" preserveAspectRatio="xMidYMid meet"/>`:text(x+size/2,y+size/2,word,22,'#315d57','text-anchor="middle"');}
function artwork(kind,cards){
 const pic=(...args)=>picture(cards,...args);
 switch(kind){
 case 'speaking':return `${rect(457,39,119,155,'#fffdf7','#bed9cb')}${pic('cat',469,48,95)}${text(516,171,'ねこ',22,'#456f63','text-anchor="middle"')}${rect(579,55,135,56,'#fff','#99cbb5',24)}${text(646,92,'cat!',30,'#438d77','text-anchor="middle" font-weight="700"')}${wave(586,147,'#74b9a5')}<g transform="translate(646 222)" stroke="#398775" stroke-width="5" fill="none"><rect x="-12" y="-34" width="24" height="40" rx="12" fill="#9dd7c4"/><path d="M-24-8v4a24 24 0 0 0 48 0v-4M0 20v15m-15 0h30"/></g>`;
 case 'abc':return `<path d="M400 38H740" stroke="#28344d" stroke-width="13" stroke-linecap="round"/><path d="M610 41v47" stroke="#8b98c4" stroke-width="6"/>${rect(580,29,60,28,'#ff8fab','#24304a',9)}<g transform="translate(610 110)"><path d="M-15 2l-16 28 10 12M15 2l16 28-10 12" fill="none" stroke="#24304a" stroke-width="11" stroke-linecap="round"/><path d="M-15 2l-16 28 10 12M15 2l16 28-10 12" fill="none" stroke="#ffd23f" stroke-width="5" stroke-linecap="round"/>${rect(-24,-22,48,29,'#3ec1d3','#24304a',9)}<circle cx="-8" cy="-7" r="5" fill="white"/><circle cx="8" cy="-7" r="5" fill="white"/><circle cx="-7" cy="-7" r="2" fill="#24304a"/><circle cx="9" cy="-7" r="2" fill="#24304a"/></g>${tile(448,162,'C','#ff8fab',-9)}${tile(541,164,'A','#ffd23f',0)}${tile(637,163,'T','#a3d9f0',9)}${pic('cat',421,58,88)}`;
 case 'nova':return `<circle cx="625" cy="133" r="142" fill="#243556" opacity=".95"/><g fill="#b0cfff"><circle cx="475" cy="42" r="3"/><circle cx="709" cy="41" r="2"/><circle cx="725" cy="216" r="3"/><circle cx="527" cy="245" r="2"/></g>${rect(471,60,100,45,'#15213e','#8a8bff',9)}${text(521,91,'cap',25,'#b7c4ff','text-anchor="middle"')}${rect(591,99,126,59,'#1d3e53','#4fd8ff',9)}${text(654,139,'cat',35,'#a0eeff','text-anchor="middle" font-weight="700"')}<g fill="none" stroke="#4fd8ff" stroke-width="3"><circle cx="654" cy="129" r="53"/><path d="M654 64v24m0 83v24m-67-66h25m83 0h24M623 218l24-31m-24 49 8-11"/></g><path d="M610 267l15-40 16 40-16-9Z" fill="#c8f7ff"/>${audio(478,168,'#9cbded')}`;
 case 'accent':return `${rect(447,42,278,119,'#fff','#d8cff2',22)}${text(481,118,'ba',28,'#a9a0c9')}${rect(526,67,78,75,'#ffbd70','none',17)}${text(565,118,'NA',35,'#9f5919','text-anchor="middle" font-weight="800"')}${text(621,118,'na',28,'#a9a0c9')}<path d="M460 221q68 15 119-29t101-3m-19-11 20 10-13 17" fill="none" stroke="#9381d4" stroke-width="5" stroke-linecap="round"/>${wave(481,188,'#b6a8e0')}${audio(685,234,'#a59ac9')}`;
 case 'hunter':return `<path d="M436 75l285 118" stroke="#ecc565" stroke-width="5" stroke-dasharray="7 10"/>${rect(452,53,112,133,'#fff9e6','#55978c',19)}${text(508,132,'cat',34,'#265c53','text-anchor="middle" font-weight="800"')}<g transform="rotate(10 650 177)">${rect(592,108,114,134,'#fff9e6','#55978c',19)}${pic('cat',602,115,92)}${text(649,226,'ねこ',21,'#265c53','text-anchor="middle"')}</g>${text(573,66,'3 COMBO!',24,'#b98628','transform="rotate(-7 573 66)" font-weight="800"')}<g fill="#e5ba52"><path d="M583 146l6 15 16 3-15 7-3 16-8-15-15-2 13-9Z"/><circle cx="728" cy="93" r="5"/></g>`;
 case 'karuta':return `<g transform="rotate(-9 504 111)">${rect(447,39,110,133,'#fff','#91b78a')}${pic('apple',456,47,91)}${text(502,158,'りんご',19,'#456b40','text-anchor="middle"')}</g><g transform="rotate(8 650 162)">${rect(587,98,116,139,'#fff','#91b78a')}${pic('cat',596,107,98)}${text(645,225,'ねこ',19,'#456b40','text-anchor="middle"')}</g>${audio(650,41,'#86aa73')}${rect(467,206,93,38,'#d5e9be','none',19)}${text(513,234,'✓',30,'#508445','text-anchor="middle"')}`;
 case 'grammar':return `${rect(445,49,269,179,'#fffdf8','#c2d7ca',19)}${rect(466,74,51,39,'#e2efe4')}${text(491,101,'I',23,'#477659','text-anchor="middle"')}${rect(526,74,64,39,'#fbe6af')}${text(558,101,'am',23,'#9f7d34','text-anchor="middle"')}${rect(599,74,94,39,'#e4e9fa')}${text(645,101,'happy.',22,'#7384b8','text-anchor="middle"')}<path d="M558 122v23m-11-10 11 11 11-11" fill="none" stroke="#beab7d" stroke-width="3"/>${text(476,178,'I am → Am I ...?',23,'#688477')}<path d="M470 199h156" stroke="#d6e1d7" stroke-width="5" stroke-linecap="round"/><circle cx="677" cy="208" r="28" fill="#d7ecdf"/>${text(677,220,'✓',31,'#42866a','text-anchor="middle"')}`;
 case 'exams':return `<g transform="rotate(7 589 146)">${rect(470,36,226,235,'#fffdf8','#d0d0bf',13)}${text(492,75,'ENGLISH  /  5',17,'#a7a88b','letter-spacing="2"')}<path d="M491 91h182" stroke="#dddfcf" stroke-width="3"/>${[0,1,2].map((n)=>`<circle cx="502" cy="${123+n*45}" r="10" fill="${n===1?'#d9e8bb':'none'}" stroke="#a3b18e" stroke-width="2"/><path d="M526 ${123+n*45}h132" stroke="#d4dbc8" stroke-width="6" stroke-linecap="round"/>`).join('')}${text(502,176,'✓',23,'#607f47','text-anchor="middle"')}</g><circle cx="698" cy="77" r="38" fill="#f8ebbb" stroke="#d5bc6c" stroke-width="3"/><path d="M698 53v24l16 10" fill="none" stroke="#a38b46" stroke-width="4" stroke-linecap="round"/>${audio(433,217,'#a9b68c')}`;
 }
 return '';
}
const features=[
 ['speaking','#speaking','SPEAK & LEARN','声でこたえる','絵を見て、英語で言ってみよう','マイクで挑戦'],
 ['abc','./abc-hand.html','SPELLING CRANE','ABC HAND','クレーンで文字を集めよう','絵と音でスペル練習'],
 ['nova','./word-nova.html','LISTEN & SHOOT','WORD NOVA','聞いて、見つけて、撃ち抜こう','にた発音も聞き分け'],
 ['accent','./accent.html','SOUND & RHYTHM','アクセントを聞き分けろ！','強い音と、声の上がり下がり','聞きくらべて選ぼう'],
 ['hunter','./hunter.html','PAIR & COMBO','たんごハンター','絵と英語のペアでコンボ！','見つけて、つなげよう'],
 ['karuta','#karuta','LISTEN & TOUCH','音声かるた','英語を聞いて、絵の札を取ろう','カテゴリ・枚数を選べる'],
 ['grammar','./grammar/','DISCOVER THE RULES','ぶんぽうラボ','図と例文で「なぜ？」がわかる','理解度チェック・AI対話'],
 ['exams','#exams','READY FOR EIKEN','英検5級 実戦テスト','読む25問 ＋ 聞く25問','全3回・すべて選択式'],
];
export function featureBanners(cards){return `<section class="feature-menu" aria-labelledby="feature-menu-title"><div class="section-head"><div><small class="eyebrow">FIND YOUR NEXT ADVENTURE</small><h2 id="feature-menu-title">今日は、どれで遊ぶ？</h2></div><span class="feature-menu-note">遊びながら、英語をひとつずつ。</span></div><div class="feature-banners">${features.map(([kind,href,label,title,description,tag])=>`<a class="feature-banner banner-${kind}" href="${href}"><svg class="feature-banner-art" viewBox="0 0 760 300" preserveAspectRatio="xMaxYMid slice" aria-hidden="true" focusable="false" font-family="'DM Sans','Noto Sans JP',sans-serif"><circle cx="653" cy="148" r="199" fill="currentColor" opacity=".055"/><path d="M35 241Q203 112 385 217T760 199" fill="none" stroke="currentColor" stroke-width="2" opacity=".05"/>${artwork(kind,cards)}</svg><span class="feature-banner-wash" aria-hidden="true"></span><span class="feature-banner-copy"><small class="feature-banner-label">${label}</small><strong>${title}</strong><span class="feature-banner-description">${description}</span><span class="feature-banner-tag">${tag}</span></span><span class="feature-banner-arrow" aria-hidden="true">↗</span></a>`).join('')}</div></section>`;}
